                        <div class="pm-logo-unit"><i class="fas fa-plane"></i> Voyage Elite</div>
                        <div class="pm-logo-unit"><i class="fas fa-umbrella-beach"></i> Resort Luxury</div>
                        <div class="pm-logo-unit"><i class="fas fa-concierge-bell"></i> Event Masters</div>
                        <div class="pm-logo-unit"><i class="fas fa-map-signs"></i> Tourism Experts</div>
                        <div class="pm-logo-unit"><i class="fas fa-briefcase"></i> Business Travel</div>
